import datetime as dt
import pytest
from tidewatch.reconcile import reconcile, Report

D = dt.date(2026, 11, 2)


def test_empty_inputs_return_empty_report():
    assert reconcile([], []) == Report.empty()


@pytest.mark.parametrize('diff,tol,matched', [(0, 0, True), (3, 5, True), (6, 5, False)])
def test_tolerance(make_entry, make_txn, diff, tol, matched):
    r = reconcile([make_entry(1000, D, 'A1')], [make_txn(1000 + diff, D, 'A1')], tolerance_cents=tol)
    assert (len(r.matched) == 1) is matched


def test_duplicate_bank_reference_flagged(make_entry, make_txn):
    r = reconcile([make_entry(500, D, 'R9')], [make_txn(500, D, 'R9'), make_txn(500, D, 'R9')])
    assert len(r.matched) == 1
    assert [t.reference for t in r.duplicates] == ['R9']


def test_date_window_fallback_matches_without_reference(make_entry, make_txn):
    r = reconcile([make_entry(700, D, None)], [make_txn(700, D + dt.timedelta(days=2), None)])
    assert len(r.matched) == 1


def test_date_window_excludes_outside(make_entry, make_txn):
    r = reconcile([make_entry(700, D, None)], [make_txn(700, D + dt.timedelta(days=4), None)])
    assert r.unmatched_ledger and r.unmatched_bank

